       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid #ffffff;
         outline-offset: 3px;
       }

       main {
         display: grid;
         min-height: 100vh;
         place-items: center;
         padding: clamp(1rem, 4vw, 4rem);
       }

       .support-card {
         width: min(100%, 42rem);
         border: 1px solid rgba(148, 163, 184, 0.28);
         border-radius: 1.5rem;
         padding: clamp(1.25rem, 4vw, 2.5rem);
         background: linear-gradient(145deg, rgba(17, 24, 39, 0.95), rgba(15, 23, 42, 0.95));
         box-shadow: var(--shadow);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent);
         font-size: 0.8rem;
         font-weight: 800;
         letter-spacing: 0.14em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 7vw, 3.75rem);
         line-height: 1;
         letter-spacing: -0.05em;
       }

       .intro {
         margin: 1rem 0 0;
         max-width: 58ch;
         color: var(--muted);
       }

       form {
         display: grid;
         gap: 1.15rem;
         margin-top: 2rem;
       }

       .required-note {
         margin: 0;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-weight: 700;
       }

       .required-marker {
         color: var(--accent);
       }

       input {
         width: 100%;
         min-height: 3.25rem;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         padding: 0.85rem 1rem;
         color: var(--text);
         background: rgba(15, 23, 42, 0.88);
         font: inherit;
         transition:
           border-color 160ms ease,
           box-shadow 160ms ease,
           background-color 160ms ease;
       }

       input:hover {
         border-color: #64748b;
       }

       input:focus-visible,
       button:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: 3px;
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
         background: var(--error-bg);
       }

       .helper-text,
       .error-message {
         margin: 0;
         font-size: 0.92rem;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-message {
         display: none;
         color: var(--error);
         font-weight: 700;
       }

       .error-message.is-visible {
         display: block;
       }

       button {
         min-height: 3.4rem;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.35rem;
         color: #03111f;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         box-shadow: 0 14px 36px rgba(56, 189, 248, 0.25);
       }

       button:hover {
         filter: brightness(1.06);
       }

       .status-message {
         min-height: 1.5rem;
         margin: 0;
         color: var(--success);
         font-weight: 700;
       }

       @media (max-width: 28rem) {
         main {
           display: block;
           padding: 1rem;
         }

         .support-card {
           border-radius: 1rem;
         }
       }

       @media (forced-colors: active) {
         .support-card,
         input,
         button {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         input[aria-invalid="true"] {
           border-color: Mark;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div id="app"></div>
     </main>

     <script>
       const fields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           invalidMessage: "Error: Enter your full name."
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           invalidMessage: "Error: Enter a valid email address, like name@example.com."
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           helperText: "Expected format: +1 555 123 4567 or 555-123-4567.",
           invalidMessage: "Error: Enter a phone number in the expected format, or leave this field blank."
         }
       ];

       const escapeHtml = (value) =>
         String(value).replace(/[&<>"']/g, (character) => ({
           "&": "&amp;",
           "<": "&lt;",
           ">": "&gt;",
           '"': "&quot;",
           "'": "&#039;"
         })[character]);

       function FormField({ id, name, label, type, autocomplete, required, helperText, invalidMessage }) {
         const helperId = `${id}-help`;
         const errorId = `${id}-error`;
         const describedBy = [helperText ? helperId : null, errorId].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${id}">
               ${escapeHtml(label)}
               ${required ? '<span class="required-marker" aria-hidden="true">*</span>' : '<span class="optional-text">(optional)</span>'}
             </label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               ${required ? "required" : ""}
               aria-describedby="${describedBy}"
               aria-invalid="false"
             >
             ${helperText ? `<p class="helper-text" id="${helperId}">${escapeHtml(helperText)}</p>` : ""}
             <p class="error-message" id="${errorId}">${escapeHtml(invalidMessage)}</p>
           </div>
         `;
       }

       function ContactSupportForm() {
         return `
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">Contact our team</h1>
             <p class="intro">
               Tell us how to reach you and a support specialist will follow up as soon as possible.
             </p>
             <form id="support-form" novalidate>
               <p class="required-note"><span aria-hidden="true">*</span> Required field</p>
               ${fields.map(FormField).join("")}
               <button type="submit">Send request</button>
               <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function isValidEmail(value) {
         return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
       }

       function isValidPhone(value) {
         return value === "" || /^\+?[0-9][0-9\s().-]{6,}[0-9]$/.test(value);
       }

       function validateField(input) {
         const value = input.value.trim();
         let valid = true;

         if (input.required && value === "") {
           valid = false;
         } else if (input.type === "email" && value !== "" && !isValidEmail(value)) {
           valid = false;
         } else if (input.type === "tel" && !isValidPhone(value)) {
           valid = false;
         }

         const error = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", String(!valid));
         error.classList.toggle("is-visible", !valid);
         return valid;
       }

       function wireFormValidation() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");
         const inputs = [...form.querySelectorAll("input")];

         inputs.forEach((input) => {
           input.addEventListener("blur", () => validateField(input));
           input.addEventListener("input", () => {
             if (input.getAttribute("aria-invalid") === "true") {
               validateField(input);
             }
             status.textContent = "";
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           const firstInvalid = inputs.find((input) => !validateField(input));

           if (firstInvalid) {
             status.textContent = "Please fix the highlighted fields before sending your request.";
             firstInvalid.focus();
             return;
           }

           status.textContent = "Thanks. Your support request is ready to send.";
           form.reset();
           inputs.forEach((input) => {
             input.setAttribute("aria-invalid", "false");
             document.getElementById(`${input.id}-error`).classList.remove("is-visible");
           });
         });
       }

       document.getElementById("app").innerHTML = ContactSupportForm();
       wireFormValidation();
     </script>
   </body>
 </html>

')

