      }

      function isValidEmail(value) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      }

      function isValidPhone(value) {
        return value === "" || /^\+?[0-9][0-9\s().-]{6,}[0-9]$/.test(value);
      }

      function validateField(input) {
        const value = input.value.trim();
        let valid = true;

        if (input.required && value === "") {
          valid = false;
        } else if (input.type === "email" && value !== "" && !isValidEmail(value)) {
          valid = false;
        } else if (input.type === "tel" && !isValidPhone(value)) {
          valid = false;
        }

        const error = document.getElementById(`${input.id}-error`);
        const helper = document.getElementById(`${input.id}-help`);
        const descriptions = [helper ? helper.id : null, !valid ? error.id : null].filter(Boolean);
